import{_ as t,o as a,c as o,l as r,t as s,N as i}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"git-remote-fd | x-cmd man (git man1) | Reflect smart transport stream back to caller","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-remote-fd - Reflect smart transport stream back to caller","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-remote-fd | x-cmd man (git man1) | Reflect smart transport stream back to caller"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-remote-fd - Reflect smart transport stream back to caller"}]]},"headers":[],"params":{"isMan":true,"man":"git-remote-fd","category":"git man1","desc":"Reflect smart transport stream back to caller"},"relativePath":"git/man1/git-remote-fd.md","filePath":"git/man1/git-remote-fd.md"}'),n={name:"git/man1/git-remote-fd.md"},c={class:"visually-hidden"},l=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-remote-fd - Reflect smart transport stream back to caller</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p>&quot;fd::&lt;infd&gt;[,&lt;outfd&gt;][/&lt;anything&gt;]&quot; (as URL)</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This helper uses specified file descriptors to connect to a remote Git server. This is not meant for end users but for programs and scripts calling git fetch, push or archive.</p><p>If only &lt;infd&gt; is given, it is assumed to be a bidirectional socket connected to remote Git server (git-upload-pack, git-receive-pack or git-upload-archive). If both &lt;infd&gt; and &lt;outfd&gt; are given, they are assumed to be pipes connected to a remote Git server (&lt;infd&gt; being the inbound pipe and &lt;outfd&gt; being the outbound pipe.</p><p>It is assumed that any handshaking procedures have already been completed (such as sending service request for git://) before this helper is started.</p><p>&lt;anything&gt; can be any string. It is ignored. It is meant for providing information to user in the URL in case that URL is displayed in some context.</p><h2 id="environment-variables" tabindex="-1">ENVIRONMENT VARIABLES <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;ENVIRONMENT VARIABLES&quot;">​</a></h2><p>GIT_TRANSLOOP_DEBUG</p><blockquote><p>If set, prints debugging information about various reads/writes.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p><strong>git fetch fd::17 master</strong></p><blockquote><p>Fetch master, using file descriptor #17 to communicate with git-upload-pack.</p></blockquote><p><strong>git fetch fd::17/foo master</strong></p><blockquote><p>Same as above.</p></blockquote><p><strong>git push fd::7,8 master (as URL)</strong></p><blockquote><p>Push master, using file descriptor #7 to read data from git-receive-pack and file descriptor #8 to write data to same service.</p></blockquote><p><strong>git push fd::7,8/bar master</strong></p><blockquote><p>Same as above.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gitremote-helpers</strong>(7)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',25);function d(e,m,p,g,h,u){return a(),o("div",null,[r("h1",c,s(e.$params.man),1),l])}const k=t(n,[["render",d]]);export{b as __pageData,k as default};
